"""Helpers to build campaign inputs and run the entry point."""
import base64, csv, io, json, os, subprocess, sys

COLUMNS=('type','id','revision','published','op','lease','event','probe',
         'target','responder','result','service','attempt','payload')

def rows_to_csv(rows):
    out=io.StringIO()
    writer=csv.writer(out,lineterminator='\n')
    writer.writerow(COLUMNS)
    for row in rows:
        writer.writerow(row)
    return out.getvalue().encode()

def b64(data):
    return base64.b64encode(data).decode('ascii')

def capture(rows, encoding='csv'):
    if isinstance(rows,bytes):
        payload=rows
    else:
        payload=rows_to_csv(rows)
    if encoding=='zstd':
        import zstandard as zstd
        payload=zstd.ZstdCompressor().compress(payload)
    return {'encoding':encoding,'chunks':[b64(payload)]}

def base_job(**kw):
    job={'version':3,'seed':'demo','leases':[],'services':[{'id':'web','kind':'tcp'}],
         'queries':[10],'captures':[],'requests':[],'offers':[],
         'request_quotas':[{'id':'all','parent':None,'capacity':4096}],
         'offer_quotas':[{'id':'all','parent':None,'capacity':4096}]}
    job.update(kw)
    return job

def lease(lid='home',prefix='2001:db8:1:1200::/64',start=0,end=100,subnets=(0,),low=2):
    return {'id':lid,'prefix':prefix,'start':start,'end':end,'subnets':list(subnets),'low_count':low}

def icmp(ident,rev,pub,lease_id,event,probe,target,responder,result,op='put'):
    return [('icmp' if op=='put' else 'icmp'),ident,str(rev),str(pub),op,lease_id,str(event),
            probe,target,responder,result,'','','']

def app(ident,rev,pub,lease_id,event,target,service,attempt,result,payload='',op='put'):
    return ['app',ident,str(rev),str(pub),op,lease_id,str(event),'',target,'',result,service,
            str(attempt),payload]

def delete(ident,kind,rev,pub,op='delete'):
    return [kind,ident,str(rev),str(pub),op,'','','','','','','','','']

def run(job, raw=None):
    data=raw if raw is not None else json.dumps(job).encode()
    proc=subprocess.run([sys.executable,'-I','-B','/workspace/submission/campaign.py'],
                         input=data,capture_output=True,env={'PATH':'/usr/local/bin:/usr/bin:/bin',
                         'HOME':'/workspace','LANG':'C','LC_ALL':'C','TMPDIR':'/workspace/tmp'})
    if proc.returncode!=0:
        raise AssertionError('exit %d stderr=%s'%(proc.returncode,proc.stderr.decode()[:2000]))
    return json.loads(proc.stdout.decode()), proc.stderr.decode()

def check(label,condition,detail=''):
    if condition:
        print('ok   %s'%label)
    else:
        print('FAIL %s %s'%(label,detail))
        globals()['FAILURES']=globals().get('FAILURES',0)+1
